from datetime import datetime
import json

MENU = [
    {'id': 'egg-pancake', 'name': '蛋餅', 'price': 35, 'soldout': False},
    {'id': 'turnip-cake', 'name': '蘿蔔糕', 'price': 40, 'soldout': False},
    {'id': 'iron-noodles', 'name': '鐵板麵', 'price': 55, 'soldout': False},
    {'id': 'chicken-nuggets', 'name': '雞塊', 'price': 45, 'soldout': False},
    {'id': 'milk-tea', 'name': '奶茶', 'price': 30, 'soldout': False},
    {'id': 'soy-milk', 'name': '豆漿', 'price': 25, 'soldout': False},
]
MENU_BY_ID = {m['id']: m for m in MENU}

DINING_OPTIONS = ('內用', '外帶')

STATUS_TODO = '待做'
STATUS_DOING = '製作中'
STATUS_DONE = '完成'
NEXT_STATUS = {STATUS_TODO: STATUS_DOING, STATUS_DOING: STATUS_DONE}

ORDERS = []
NEXT_ID = 1


def _parse_body(body):
    if not body:
        return None
    try:
        return json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, ValueError):
        return None


def _create_order(data):
    global NEXT_ID
    if not isinstance(data, dict):
        return 400, {'error': '請求內容必須是 JSON 物件'}
    table = data.get('table')
    if not isinstance(table, str) or not table.strip():
        return 400, {'error': '桌號不可為空'}
    dining = data.get('dining')
    if not isinstance(dining, str) or dining not in DINING_OPTIONS:
        return 400, {'error': '請選擇內用或外帶'}
    raw_items = data.get('items')
    if not isinstance(raw_items, list):
        return 400, {'error': '品項格式錯誤'}

    lines = []
    total = 0
    for entry in raw_items:
        if not isinstance(entry, dict):
            return 400, {'error': '品項格式錯誤'}
        item_id = entry.get('id')
        qty = entry.get('qty')
        if not isinstance(item_id, str) or item_id not in MENU_BY_ID:
            return 400, {'error': '未知的餐點'}
        if isinstance(qty, bool) or not isinstance(qty, int) or qty < 0:
            return 400, {'error': '數量必須為非負整數'}
        if qty == 0:
            continue
        m = MENU_BY_ID[item_id]
        if m['soldout']:
            return 400, {'error': '「' + m['name'] + '」目前缺貨，無法點餐'}
        subtotal = m['price'] * qty
        total += subtotal
        lines.append({
            'id': m['id'],
            'name': m['name'],
            'price': m['price'],
            'qty': qty,
            'subtotal': subtotal,
        })
    if not lines:
        return 400, {'error': '請至少選擇一項餐點'}

    now = datetime.now().astimezone()
    order = {
        'id': NEXT_ID,
        'table': table.strip(),
        'dining': dining,
        'items': lines,
        'total': total,
        'status': STATUS_TODO,
        'created_at': now.isoformat(timespec='seconds'),
        'date': now.date().isoformat(),
    }
    ORDERS.append(order)
    NEXT_ID += 1
    return 201, {'order': order}


def _update_status(order_id, data):
    if not isinstance(data, dict):
        return 400, {'error': '請求內容必須是 JSON 物件'}
    new_status = data.get('status')
    if new_status not in (STATUS_DOING, STATUS_DONE):
        return 400, {'error': '狀態值不正確'}
    order = None
    for o in ORDERS:
        if o['id'] == order_id:
            order = o
            break
    if order is None:
        return 404, {'error': '找不到訂單'}
    if NEXT_STATUS.get(order['status']) != new_status:
        return 409, {'error': '不允許的狀態轉換'}
    order['status'] = new_status
    return 200, {'order': order}


def _set_soldout(item, data):
    if not isinstance(data, dict):
        return 400, {'error': '請求內容必須是 JSON 物件'}
    value = data.get('soldout')
    if not isinstance(value, bool):
        return 400, {'error': '缺貨狀態必須是 true 或 false'}
    item['soldout'] = value
    return 200, {'item': dict(item)}


def _sales_today():
    today = datetime.now().astimezone().date().isoformat()
    count = 0
    total = 0
    counts = {}
    for o in ORDERS:
        if o['date'] == today:
            count += 1
            total += o['total']
            for line in o['items']:
                counts[line['id']] = counts.get(line['id'], 0) + line['qty']
    ranked = [(idx, m) for idx, m in enumerate(MENU) if counts.get(m['id'], 0) > 0]
    ranked.sort(key=lambda pair: (-counts[pair[1]['id']], pair[0]))
    top_items = [
        {'id': m['id'], 'name': m['name'], 'qty': counts[m['id']]}
        for _, m in ranked[:3]
    ]
    return 200, {'date': today, 'count': count, 'total': total, 'top_items': top_items}


def handle(method: str, path: str, body: bytes) -> tuple[int, dict]:
    method = method.upper()
    parts = [p for p in path.split('/') if p]

    if parts == ['menu']:
        if method != 'GET':
            return 405, {'error': '方法不允許'}
        return 200, {'items': [dict(m) for m in MENU]}

    if len(parts) == 3 and parts[0] == 'menu' and parts[2] == 'soldout':
        if method != 'PATCH':
            return 405, {'error': '方法不允許'}
        item = MENU_BY_ID.get(parts[1])
        if item is None:
            return 404, {'error': '找不到餐點'}
        data = _parse_body(body)
        if data is None:
            return 400, {'error': 'JSON 格式錯誤'}
        return _set_soldout(item, data)

    if parts == ['orders']:
        if method == 'GET':
            orders = sorted(ORDERS, key=lambda o: (o['created_at'], o['id']))
            return 200, {'orders': orders}
        if method == 'POST':
            data = _parse_body(body)
            if data is None:
                return 400, {'error': 'JSON 格式錯誤'}
            return _create_order(data)
        return 405, {'error': '方法不允許'}

    if len(parts) == 3 and parts[0] == 'orders' and parts[2] == 'status':
        if method != 'PATCH':
            return 405, {'error': '方法不允許'}
        if not (parts[1].isascii() and parts[1].isdigit()):
            return 404, {'error': '找不到訂單'}
        data = _parse_body(body)
        if data is None:
            return 400, {'error': 'JSON 格式錯誤'}
        return _update_status(int(parts[1]), data)

    if parts == ['sales', 'today']:
        if method != 'GET':
            return 405, {'error': '方法不允許'}
        return _sales_today()

    return 404, {'error': '找不到端點'}

