const STATUS_CLASS = { '待做': 'status-todo', '製作中': 'status-doing', '完成': 'status-done' };
const NEXT_STATUS = { '待做': '製作中', '製作中': '完成' };
const NEXT_LABEL = { '待做': '開始製作', '製作中': '標示完成' };
const DINING_CLASS = { '內用': 'tag-dinein', '外帶': 'tag-takeout' };
let menu = [];
const cart = {};

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

async function api(path, options) {
  let res;
  try {
    res = await fetch(path, options);
  } catch (err) {
    throw new Error('網路連線失敗，請稍後再試');
  }
  let data = null;
  try {
    data = await res.json();
  } catch (err) {
    data = null;
  }
  if (!res.ok) {
    throw new Error((data && data.error) || ('請求失敗（' + res.status + '）'));
  }
  return data;
}

function showMessage(id, text, isError) {
  const node = document.getElementById(id);
  node.textContent = text;
  node.className = isError ? 'message error' : 'message ok';
}

function cartTotal() {
  return menu.reduce((sum, m) => sum + m.price * (cart[m.id] || 0), 0);
}

function renderMenu() {
  const container = document.getElementById('menu');
  container.textContent = '';
  for (const m of menu) {
    const row = el('div', m.soldout ? 'menu-row soldout' : 'menu-row');
    const nameBox = el('span', 'dish-name', m.name);
    if (m.soldout) {
      nameBox.appendChild(el('span', 'soldout-label', '缺貨'));
    }
    row.appendChild(nameBox);
    row.appendChild(el('span', 'dish-price', m.price + ' 元'));
    const controls = el('div', 'qty-controls');
    const minus = el('button', '', '−');
    minus.type = 'button';
    minus.disabled = !!m.soldout;
    minus.setAttribute('aria-label', m.name + ' 減少');
    minus.addEventListener('click', () => changeQty(m.id, -1));
    const qty = el('span', 'qty', String(cart[m.id] || 0));
    qty.id = 'qty-' + m.id;
    const plus = el('button', '', '+');
    plus.type = 'button';
    plus.disabled = !!m.soldout;
    plus.setAttribute('aria-label', m.name + ' 增加');
    plus.addEventListener('click', () => changeQty(m.id, 1));
    controls.appendChild(minus);
    controls.appendChild(qty);
    controls.appendChild(plus);
    row.appendChild(controls);
    container.appendChild(row);
  }
  document.getElementById('cart-total').textContent = String(cartTotal());
}

function changeQty(id, delta) {
  const m = menu.find((x) => x.id === id);
  if (!m || m.soldout) return;
  cart[id] = Math.max(0, (cart[id] || 0) + delta);
  document.getElementById('qty-' + id).textContent = String(cart[id]);
  document.getElementById('cart-total').textContent = String(cartTotal());
}

function applyMenu(items) {
  menu = items;
  for (const m of menu) {
    if (m.soldout) cart[m.id] = 0;
  }
  renderMenu();
}

async function loadMenu() {
  try {
    const data = await api('api/menu');
    applyMenu(data.items);
  } catch (err) {
    showMessage('order-message', err.message, true);
  }
}

function selectedDining() {
  const checked = document.querySelector('input[name=dining]:checked');
  return checked ? checked.value : '';
}

async function submitOrder() {
  const table = document.getElementById('table-input').value.trim();
  const dining = selectedDining();
  const items = menu
    .filter((m) => !m.soldout && (cart[m.id] || 0) > 0)
    .map((m) => ({ id: m.id, qty: cart[m.id] }));
  if (!dining) {
    showMessage('order-message', '請選擇內用或外帶', true);
    return;
  }
  if (!table) {
    showMessage('order-message', '請輸入桌號', true);
    return;
  }
  if (items.length === 0) {
    showMessage('order-message', '請至少選擇一項餐點', true);
    return;
  }
  const btn = document.getElementById('submit-btn');
  btn.disabled = true;
  try {
    const data = await api('api/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ table: table, dining: dining, items: items })
    });
    for (const m of menu) {
      cart[m.id] = 0;
    }
    document.getElementById('table-input').value = '';
    renderMenu();
    showMessage('order-message', '訂單已送出（' + data.order.dining + '），訂單編號 #' + data.order.id, false);
  } catch (err) {
    showMessage('order-message', err.message, true);
    await refreshMenuQuietly();
  } finally {
    btn.disabled = false;
  }
}

async function refreshMenuQuietly() {
  try {
    const data = await api('api/menu');
    applyMenu(data.items);
  } catch (err) {
    /* 保留原本的錯誤訊息 */
  }
}

async function loadOrders() {
  try {
    const data = await api('api/orders');
    renderOrders(data.orders);
    showMessage('kitchen-message', '', false);
  } catch (err) {
    showMessage('kitchen-message', err.message, true);
  }
}

function renderOrders(orders) {
  const box = document.getElementById('orders');
  box.textContent = '';
  if (orders.length === 0) {
    box.appendChild(el('p', 'empty', '目前沒有訂單'));
    return;
  }
  for (const o of orders) {
    const cls = STATUS_CLASS[o.status] || '';
    const card = el('article', 'order-card ' + cls);
    const head = el('div', 'order-head');
    const title = el('strong', '', '#' + o.id + '　桌號 ' + o.table);
    const left = el('span', 'order-title');
    left.appendChild(title);
    if (o.dining) {
      left.appendChild(el('span', 'tag ' + (DINING_CLASS[o.dining] || ''), o.dining));
    }
    head.appendChild(left);
    head.appendChild(el('span', 'badge ' + cls, o.status));
    card.appendChild(head);
    const list = el('ul', 'order-items');
    for (const line of o.items) {
      list.appendChild(el('li', '', line.name + ' × ' + line.qty + '（' + line.subtotal + ' 元）'));
    }
    card.appendChild(list);
    card.appendChild(el('div', 'order-total', '合計 ' + o.total + ' 元　下單時間 ' + o.created_at.replace('T', ' ')));
    const next = NEXT_STATUS[o.status];
    if (next) {
      const btn = el('button', 'primary', NEXT_LABEL[o.status]);
      btn.type = 'button';
      btn.addEventListener('click', () => changeStatus(o.id, next));
      card.appendChild(btn);
    }
    box.appendChild(card);
  }
}

async function changeStatus(orderId, status) {
  try {
    await api('api/orders/' + orderId + '/status', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: status })
    });
    await loadOrders();
  } catch (err) {
    showMessage('kitchen-message', err.message, true);
  }
}

function renderStock(items) {
  const box = document.getElementById('stock');
  box.textContent = '';
  for (const m of items) {
    const row = el('div', m.soldout ? 'stock-row soldout' : 'stock-row');
    row.appendChild(el('span', 'dish-name', m.name));
    row.appendChild(el('span', 'stock-state', m.soldout ? '缺貨中' : '供應中'));
    const btn = el('button', m.soldout ? '' : 'danger', m.soldout ? '恢復供應' : '標成缺貨');
    btn.type = 'button';
    btn.addEventListener('click', () => toggleSoldout(m.id, !m.soldout));
    row.appendChild(btn);
    box.appendChild(row);
  }
}

async function loadStock() {
  try {
    const data = await api('api/menu');
    applyMenu(data.items);
    renderStock(data.items);
  } catch (err) {
    showMessage('kitchen-message', err.message, true);
  }
}

async function toggleSoldout(id, soldout) {
  try {
    await api('api/menu/' + id + '/soldout', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ soldout: soldout })
    });
    showMessage('kitchen-message', '', false);
    await loadStock();
  } catch (err) {
    showMessage('kitchen-message', err.message, true);
  }
}

async function loadSales() {
  const box = document.getElementById('sales');
  const top = document.getElementById('top3');
  try {
    const d = await api('api/sales/today');
    box.textContent = '';
    box.appendChild(el('p', '', '日期：' + d.date));
    box.appendChild(el('p', '', '今日訂單數：' + d.count));
    box.appendChild(el('p', 'sales-total', '今日營業額：' + d.total + ' 元'));
    top.textContent = '';
    const ranking = d.top_items || [];
    if (ranking.length === 0) {
      top.appendChild(el('p', 'empty', '尚無資料'));
    } else {
      const list = el('ol', 'top3-list');
      for (const t of ranking) {
        list.appendChild(el('li', '', t.name + '　' + t.qty + ' 份'));
      }
      top.appendChild(list);
    }
  } catch (err) {
    box.textContent = '';
    top.textContent = '';
    box.appendChild(el('p', 'message error', err.message));
  }
}

function showTab(name) {
  for (const btn of document.querySelectorAll('.tab')) {
    btn.classList.toggle('active', btn.dataset.tab === name);
  }
  for (const sec of document.querySelectorAll('.panel')) {
    sec.classList.toggle('hidden', sec.id !== 'tab-' + name);
  }
  if (name === 'order') loadMenu();
  if (name === 'kitchen') {
    loadOrders();
    loadStock();
  }
  if (name === 'sales') loadSales();
}

function init() {
  for (const btn of document.querySelectorAll('.tab')) {
    btn.addEventListener('click', () => showTab(btn.dataset.tab));
  }
  document.getElementById('submit-btn').addEventListener('click', submitOrder);
  document.getElementById('refresh-kitchen').addEventListener('click', () => {
    loadOrders();
    loadStock();
  });
  document.getElementById('refresh-sales').addEventListener('click', loadSales);
  loadMenu();
}

init();

